usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Videos.DownloadContent(
		context.TODO(),
		"video_123",
		openai.VideoDownloadContentParams{
			Variant: param.NewOpt[openai.VideoContentVariant](openai.VideoContentVariantVideo),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
